# api/views.py - Document Processing Service
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
from lxml import etree
import io
import logging

logger = logging.getLogger(__name__)


class DocumentParseView(APIView):
    """Parse XML documents for metadata extraction.
    Used internally by the document indexing pipeline."""

    def post(self, request):
        content_type = request.content_type or ''

        if 'xml' not in content_type and 'text/plain' not in content_type:
            return Response(
                {'error': 'Content-Type must be application/xml or text/plain'},
                status=status.HTTP_415_UNSUPPORTED_MEDIA_TYPE
            )

        raw_body = request.body
        if not raw_body:
            return Response(
                {'error': 'Empty request body'},
                status=status.HTTP_400_BAD_REQUEST
            )

        try:
            # Parse the XML document
            parser = etree.XMLParser(
                resolve_entities=True,
                load_dtd=True,
                no_network=False
            )
            doc = etree.parse(io.BytesIO(raw_body), parser)
            root = doc.getroot()

            # Extract metadata fields
            metadata = {}
            for child in root:
                tag = etree.QName(child.tag).localname if '}' in child.tag else child.tag
                metadata[tag] = child.text or ''

            # Extract attributes from root
            metadata['_root_tag'] = root.tag
            metadata['_attributes'] = dict(root.attrib)

            logger.info(f"Parsed document with {len(metadata)} metadata fields")

            return Response({
                'status': 'success',
                'metadata': metadata,
                'field_count': len(metadata)
            })

        except etree.XMLSyntaxError as e:
            logger.warning(f"XML syntax error: {e}")
            return Response(
                {'error': f'Invalid XML: {str(e)}'},
                status=status.HTTP_400_BAD_REQUEST
            )
        except Exception as e:
            logger.error(f"Unexpected error parsing document: {e}")
            return Response(
                {'error': 'Internal processing error'},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR
            )


class DocumentValidateView(APIView):
    """Validate XML against known schemas."""

    def post(self, request):
        schema_name = request.query_params.get('schema', 'default')
        raw_body = request.body

        if not raw_body:
            return Response(
                {'error': 'Empty request body'},
                status=status.HTTP_400_BAD_REQUEST
            )

        try:
            parser = etree.XMLParser(
                resolve_entities=True,
                load_dtd=True,
                no_network=False
            )
            doc = etree.parse(io.BytesIO(raw_body), parser)

            # Basic well-formedness check
            root = doc.getroot()
            is_valid = root is not None and len(root) > 0

            return Response({
                'valid': is_valid,
                'schema': schema_name,
                'root_element': root.tag if root is not None else None
            })

        except etree.XMLSyntaxError as e:
            return Response({
                'valid': False,
                'error': str(e)
            }, status=status.HTTP_400_BAD_REQUEST)


